var F=0.38; // photon flight time inside each PHOTON layer
var a=0,p=0;
for (var i=1;i<=thisComp.numLayers;i++){var l=thisComp.layer(i);
 if(l.name.indexOf("ATOM ")==0 && time>=l.inPoint) a++;
 if(l.name.indexOf("PHOTON ")==0 && time>=l.inPoint+F) p++;}
function pad(n){return (n<10?"0":"")+n;}
"ATOMS "+pad(a)+"/16\rPHOTONS "+pad(p)+"/16\r\u03C4 +"+pad(p)

var F=0.38, DRAW=0.25, n=0; // flight time, bond draw-on time
for (var i=1;i<=thisComp.numLayers;i++){var l=thisComp.layer(i);
 if(l.name.indexOf("PHOTON ")==0){var a=time-(l.inPoint+F);
  if(a>=0){var x=Math.min(1,a/DRAW); n+=l.effect("Bond count")(1)*(1-Math.pow(1-x,3));}}}
n

